import { TestBed } from '@angular/core/testing';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import fixture from './agent-contract.fixture.json';
import { AgentApi, AgentEventDecoder, type AgentStreamRequest } from './agent-api';
import type { AgentCommand, AgentEvent, AgentSession } from './agent.models';
import { FETCH } from './chat-api';

// Generated by bff/tests/test_agent_contract.py. These tests only load static data;
// they never start Python, a server, a provider, or a real fetch implementation.
interface RecordedRequest {
  method: 'POST' | 'PATCH';
  url: string;
  body: { request_id: string; [key: string]: unknown };
}
interface Control {
  http: RecordedRequest;
  status: number;
  session: AgentSession;
}
interface Exchange {
  name: string;
  baseline: AgentSession;
  command: AgentCommand;
  http: RecordedRequest;
  sse: string;
  terminal: AgentSession;
  controls?: Control[];
}
interface ErrorExchange {
  name: string;
  baseline: AgentSession;
  command: AgentCommand;
  http: RecordedRequest;
  status: number;
  body: { error: { code: string; message: string } };
}
const contract = fixture as unknown as {
  version: number;
  streams: Exchange[];
  errors: ErrorExchange[];
};
const BASE = '/api/agent/sessions';

function streamRequest(entry: Pick<Exchange, 'baseline' | 'command' | 'http'>): AgentStreamRequest {
  return {
    session_id: entry.baseline.id,
    request_id: entry.http.body.request_id,
    sequence: entry.baseline.sequence,
    snapshot: entry.baseline,
    command: entry.command,
  };
}

/** Independent expected-value extraction; all raw frames reach the real decoder. */
function recordedFrames(raw: string) {
  expect(raw.endsWith('\n\n')).toBe(true);
  return raw
    .slice(0, -2)
    .split('\n\n')
    .map((block) => {
      const fields = Object.fromEntries(
        block.split('\n').map((line) => {
          const separator = line.indexOf(': ');
          return [line.slice(0, separator), line.slice(separator + 2)];
        }),
      );
      expect(Object.keys(fields).sort()).toEqual(['data', 'event', 'id']);
      expect(fields['event']).toBe('agent');
      const event = JSON.parse(fields['data']) as AgentEvent;
      expect(fields['id']).toBe(String(event.sequence));
      return { frame: { event: fields['event'], id: fields['id'], data: fields['data'] }, event };
    });
}

function chunkedResponse(raw: string): Response {
  const bytes = new TextEncoder().encode(raw);
  const sizes = [1, 7, 31, 2, 113];
  // Deliberately split the first non-ASCII code point, as well as SSE lines/JSON.
  const utf8Split = bytes.findIndex((byte) => byte >= 0xc0) + 1;
  let offset = 0;
  let part = 0;
  return new Response(
    new ReadableStream<Uint8Array>({
      pull(controller) {
        if (offset === bytes.length) {
          controller.close();
          return;
        }
        let end = Math.min(bytes.length, offset + sizes[part++ % sizes.length]);
        if (offset < utf8Split && end > utf8Split) end = utf8Split;
        controller.enqueue(bytes.slice(offset, end));
        offset = end;
      },
    }),
    { headers: { 'Content-Type': 'text/event-stream' } },
  );
}

describe('backend-generated Agent wire contract', () => {
  let fetchDouble: ReturnType<typeof vi.fn<typeof fetch>>;
  let api: AgentApi;

  beforeEach(() => {
    fetchDouble = vi.fn<typeof fetch>();
    TestBed.configureTestingModule({ providers: [{ provide: FETCH, useValue: fetchDouble }] });
    api = TestBed.inject(AgentApi);
  });
  afterEach(() => TestBed.resetTestingModule());

  function expectRequest(
    expected: RecordedRequest,
    input: RequestInfo | URL,
    options?: RequestInit,
  ) {
    expect(String(input)).toBe(expected.url);
    expect(options?.method).toBe(expected.method);
    expect(JSON.parse(String(options?.body))).toEqual(expected.body);
    const headers = new Headers(options?.headers);
    expect(headers.get('Content-Type')).toBe('application/json');
    expect(options?.signal).toBeInstanceOf(AbortSignal);
  }

  it('keeps all regression conditions in the generated fixture', () => {
    expect(contract.version).toBe(1);
    expect(contract.streams.map((entry) => entry.name)).toEqual([
      'planning',
      'revision',
      'execution',
      'stale_baseline',
      'cancellation_archive',
      'backwards_clock',
    ]);
    const byName = Object.fromEntries(contract.streams.map((entry) => [entry.name, entry]));
    const planning = byName['planning'].terminal.runs[0];
    const revision = byName['revision'].terminal.runs[0];
    expect(planning.plan?.revision).toBe(1);
    expect(revision.plan?.revision).toBe(2);
    expect(revision.plan?.id).toBe(planning.plan?.id);
    expect(revision.plan?.digest).toMatch(/^[a-f0-9]{64}$/);
    expect(revision.plan?.digest).not.toBe(planning.plan?.digest);
    const execution = recordedFrames(byName['execution'].sse);
    expect(execution[0].event.operation_id).not.toBe(
      recordedFrames(byName['revision'].sse)[0].event.operation_id,
    );
    expect(execution.at(-1)?.event.session.runs[0].operation_id).toBeNull();
    const stale = byName['stale_baseline'];
    expect(recordedFrames(stale.sse)[0].event.sequence).toBe(stale.baseline.sequence + 2);
    const backwards = byName['backwards_clock'];
    const times = recordedFrames(backwards.sse).map(({ event }) => Date.parse(event.time));
    expect(times[2]).toBeLessThan(times[1]);
    expect(Date.parse(backwards.terminal.updated_at)).toBeLessThan(
      Date.parse(backwards.terminal.created_at),
    );
    const foreign = recordedFrames(byName['cancellation_archive'].sse);
    expect(foreign.map(({ event }) => event.type)).toEqual([
      'run.approved',
      'run.executing',
      'tool.intent',
      'session.updated',
      'run.cancelling',
      'session.updated',
      'session.archive_pending',
      'run.cancelled',
    ]);
    for (const [index, requestId] of [
      [3, 'old-stop'],
      [5, 'stop'],
      [6, 'archive'],
    ] as const) {
      expect(foreign[index].event).toMatchObject({
        request_id: requestId,
        run_id: null,
        operation_id: null,
      });
    }
  });

  it.each(contract.streams)('accepts every chunked BFF frame and reloads $name', async (entry) => {
    const expected = recordedFrames(entry.sse);
    const response = chunkedResponse(entry.sse);
    const signal = new AbortController().signal;
    fetchDouble.mockImplementation(async (input, options) => {
      if (options?.method === 'POST') {
        expectRequest(entry.http, input, options);
        expect(new Headers(options.headers).get('Accept')).toBe('text/event-stream');
        return response;
      }
      expect(String(input)).toBe(`${BASE}/${entry.baseline.id}`);
      expect(options?.method).toBe('GET');
      expect(options?.body).toBeUndefined();
      return Response.json(entry.terminal);
    });
    const request = streamRequest(entry);
    const decoder = new AgentEventDecoder(request);
    const received: AgentEvent[] = [];
    await api.stream(request, signal, (event) => {
      const recorded = expected[received.length];
      expect(event).toEqual(recorded.event);
      expect(decoder.decode(recorded.frame)).toEqual(event);
      received.push(event);
    });
    // Exact equality/count prevents silently filtering foreign session records.
    expect(received).toEqual(expected.map(({ event }) => event));
    expect(decoder.terminal).toBe(true);
    expect(response.body?.locked).toBe(false);
    expect(await api.get(entry.baseline.id, signal)).toEqual(entry.terminal);
    expect(received.at(-1)?.session).toEqual(entry.terminal);
    expect(fetchDouble.mock.calls.map(([, options]) => options?.method)).toEqual(['POST', 'GET']);
  });

  it.each(contract.streams)('accepts the standalone terminal GET for $name', async (entry) => {
    fetchDouble.mockResolvedValueOnce(Response.json(entry.terminal));
    expect(await api.get(entry.baseline.id, new AbortController().signal)).toEqual(entry.terminal);
    expect(fetchDouble).toHaveBeenCalledOnce();
  });

  it('preserves bounded read metadata and split UTF-8 through streaming and GET', async () => {
    const entry = contract.streams.find((value) => value.name === 'execution')!;
    fetchDouble.mockResolvedValueOnce(chunkedResponse(entry.sse));
    const received: AgentEvent[] = [];
    await api.stream(streamRequest(entry), new AbortController().signal, (event) =>
      received.push(event),
    );
    const result = received.at(-1)!.session.runs[0].results[0];
    expect(result).toMatchObject({
      status: 'completed',
      content: '1: alpha 🌱\n2: beta',
      path: 'public.txt',
      offset: 1,
      returned_lines: 2,
      truncated: true,
    });
    fetchDouble.mockResolvedValueOnce(Response.json(entry.terminal));
    const reloaded = await api.get(entry.baseline.id, new AbortController().signal);
    expect(reloaded.runs[0].results[0]).toEqual(result);
    expect(reloaded.runs[0].answer).toBe(
      'Completed 1 approved file read(s). See the recorded excerpts.',
    );
  });

  const controls = contract.streams.flatMap((entry) =>
    (entry.controls ?? []).map((control) => ({
      entry,
      ...control,
      name: control.http.body.request_id,
    })),
  );
  it.each(controls)(
    'uses the recorded control URL/body and snapshot for $name',
    async (control) => {
      fetchDouble.mockImplementation(async (input, options) => {
        expectRequest(control.http, input, options);
        return Response.json(control.session, { status: control.status });
      });
      const { entry, http } = control;
      const signal = new AbortController().signal;
      const sid = entry.baseline.id;
      let response: AgentSession;
      if (http.method === 'PATCH') {
        response = await api.patch(
          sid,
          http.body.request_id,
          { title: http.body['title'] as string },
          signal,
        );
      } else if (http.url.endsWith('/archive')) {
        response = await api.archive(sid, http.body.request_id, signal);
      } else {
        if (entry.command.action !== 'execute') throw new Error('Expected an execution control');
        response = await api.cancel(
          sid,
          entry.command.run_id,
          http.body.request_id,
          http.body['operation_id'] as string,
          signal,
        );
      }
      expect(response).toEqual(control.session);
      expect(fetchDouble).toHaveBeenCalledOnce();
    },
  );

  it.each(contract.errors)(
    'surfaces BFF $status $name JSON and recovers by GET only',
    async (entry) => {
      fetchDouble.mockImplementationOnce(async (input, options) => {
        expectRequest(entry.http, input, options);
        return Response.json(entry.body, { status: entry.status });
      });
      const emit = vi.fn();
      const signal = new AbortController().signal;
      await expect(api.stream(streamRequest(entry), signal, emit)).rejects.toMatchObject({
        code: `http_${entry.status}`,
        message: expect.stringContaining(entry.body.error.message),
      });
      expect(emit).not.toHaveBeenCalled();
      expect(fetchDouble).toHaveBeenCalledOnce();
      fetchDouble.mockResolvedValueOnce(Response.json(entry.baseline));
      expect(await api.get(entry.baseline.id, signal)).toEqual(entry.baseline);
      expect(fetchDouble.mock.calls.map(([, options]) => options?.method)).toEqual(['POST', 'GET']);
      expect(contract.errors.map((value) => value.body.error.code)).toEqual([
        'duplicate_command',
        'agent_not_configured',
      ]);
    },
  );
});
